#include <iostream>
#include <string>

template<class T>
T larger(const T& left, const T& right)
{
    return left < right ? right : left;
}

template<class T>
struct Box {
    T value;
};

int main()
{
    const Box<int> pages{larger(4, 9)};
    const Box<std::string> title{larger(std::string{"Atlas"}, std::string{"Orbits"})};
    std::cout << pages.value << '\n' << title.value << '\n';
}
